s = ""
def compliment(dna_string):
    reverse_compliment = ""
    reverse = "".join(reversed(dna_string))
    for char in reverse:
        if char == "A":
            reverse_compliment += "T"
        elif char == "T":
            reverse_compliment += "A"
        elif char == "C":
            reverse_compliment += "G"
        elif char == "G":
            reverse_compliment += "C"
        else:
            break
    print(reverse_compliment)
compliment(s)
